	const duration = (S.speed == 0) ? 10000 : S.speed * 60000; // 10s if zero, otherwise 1-255 minutes
	const elapsed = (S.now - E.step) >>> 0;
	let expectedSteps = Math.floor(elapsed * totalSteps / duration); // uint64_t maths, exact in a double
